def largest_palindrome(A, n):
    """Write a function to find the largest palindromic number in the given array."""
    if A is None:
        return None
    try:
        n = int(n)
    except (TypeError, ValueError):
        return None
    if n <= 0:
        return None
    largest = None
    for x in A[:n]:
        s = str(x)
        if s == s[::-1]:
            if largest is None or x > largest:
                largest = x
    return largest
